func TestTunnelRepresentationLengthIsNotBodySize(t *testing.T) {
	// HEAD and 304 may describe a representation larger than the transferred body.
	// Only the stateful HTTP executor knows whether a body is permitted.
	frame := openFrame(t)
	length := int64(1 << 40)
	frame.Payload = &pb.ExecuteFrame_ResponseStart{ResponseStart: &pb.ResponseMetadata{StatusCode: 304, Protocol: pb.HTTPVersion_HTTP_VERSION_2, ContentLength: &length}}
	if _, err := MarshalExecute(frame); err != nil {
		t.Fatalf("representation metadata rejected: %v", err)
	}
	length = -2
	if _, err := MarshalExecute(frame); err == nil {
		t.Fatal("invalid negative length accepted")
	}
}

