func TestTunnelEveryPayload(t *testing.T) {
	rev := &pb.RevisionState{Revision: 2, ConfigHash: bytes.Repeat([]byte{1}, 32)}
	controls := []*pb.ControlFrame{controlFrame(t), controlFrame(t), controlFrame(t), controlFrame(t), controlFrame(t), controlFrame(t)}
	controls[0].Payload = &pb.ControlFrame_Prepared{Prepared: rev}
	controls[1].Payload = &pb.ControlFrame_Activate{Activate: &pb.ActivateRevision{ExpectedOldRevision: 1, Next: rev}}
	controls[2].Payload = &pb.ControlFrame_Active{Active: rev}
	controls[3].Payload = &pb.ControlFrame_Reconcile{Reconcile: &pb.Reconcile{}}
	controls[4].Payload = &pb.ControlFrame_State{State: &pb.ControlState{Active: rev, Ready: true}}
	controls[5].Payload = &pb.ControlFrame_SessionClosed{SessionClosed: &pb.SessionClosed{Reason: pb.SessionCloseReason_SESSION_CLOSE_REASON_INVALID_TOKEN}}
	for _, frame := range controls {
		data, err := MarshalControl(frame)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := UnmarshalControl(data); err != nil {
			t.Fatal(err)
		}
	}
	frames := []*pb.ExecuteFrame{openFrame(t), openFrame(t), openFrame(t), openFrame(t), openFrame(t), openFrame(t)}
	frames[0].Payload = &pb.ExecuteFrame_OpenAck{OpenAck: &pb.OpenAck{Result: pb.AdmissionResult_ADMISSION_RESULT_ACCEPTED}}
	frames[1].Payload = &pb.ExecuteFrame_RequestEnd{RequestEnd: &pb.End{Complete: true}}
	frames[2].Payload = &pb.ExecuteFrame_Informational{Informational: &pb.ResponseMetadata{StatusCode: 103, Protocol: pb.HTTPVersion_HTTP_VERSION_2}}
	frames[3].Payload = &pb.ExecuteFrame_WindowUpdate{WindowUpdate: &pb.WindowUpdate{Direction: pb.Direction_DIRECTION_RESPONSE, CreditBytes: 262144}}
	frames[4].Payload = &pb.ExecuteFrame_Cancel{Cancel: &pb.Termination{Direction: pb.Direction_DIRECTION_BOTH, Code: pb.ErrorCode_ERROR_CODE_CLIENT_DISCONNECTED}}
	frames[5].Payload = &pb.ExecuteFrame_Error{Error: &pb.Termination{Direction: pb.Direction_DIRECTION_REQUEST, Code: pb.ErrorCode_ERROR_CODE_REQUEST_TIMEOUT}}
	for _, frame := range frames {
		data, err := MarshalExecute(frame)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := UnmarshalExecute(data); err != nil {
			t.Fatal(err)
		}
	}
	for _, name := range []string{"request-data.bin", "response-start.bin", "response-end.bin"} {
		if _, err := UnmarshalExecute(fixture(t, name)); err != nil {
			t.Fatal(err)
		}
	}
}

